package JavaPrograms;

public class DowhileLoop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//Ascending order
		int i =1;
		do {
			System.out.println(i);
			i++;
		}while(i<=10);
		
		
		//Descending Order 
		int j =10;
		do {
			System.out.println(j);
			j--;
		}while(j>=1);

	}

}
